import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"URI プロトコル(lertaro://)","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/uri-protocol.md","filePath":"ja-JP/user-guide/uri-protocol.md","lastUpdated":1786513079000}'),r={name:"ja-JP/user-guide/uri-protocol.md"};function c(s,e,l,n,i,p){return a(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="uri-プロトコル-lertaro" tabindex="-1">URI プロトコル(lertaro://) <a class="header-anchor" href="#uri-プロトコル-lertaro" aria-label="Permalink to &quot;URI プロトコル(lertaro://)&quot;">​</a></h1><p>Lertaro は <code>lertaro://</code> リンクのハンドラーとして自身を登録します — 別途インストール手順は不要で、アプリを初めて実行したときに自動的に設定されます。これにより、リンクを開けるもの(ブラウザ、ショートカット、他のアプリ、スクリプトなど)から、ホットキー経由でしか到達できなかった Lertaro の特定の部分に直接ジャンプできるようになります。</p><p>Lertaro がまだ実行されていない場合、<code>lertaro://</code> リンクを開くとアプリが起動し、その後リンクに従って処理されます。すでに実行中の場合は、実行中のインスタンスがそのリンクを直接処理します — 2つ目のコピーが起動することはありません。</p><h2 id="ルート" tabindex="-1">ルート <a class="header-anchor" href="#ルート" aria-label="Permalink to &quot;ルート&quot;">​</a></h2><table tabindex="0"><thead><tr><th>リンク</th><th>動作</th></tr></thead><tbody><tr><td><code>lertaro://</code></td><td>クイック検索ウィンドウをアクティブにします — ホットキーで呼び出した場合と同じです。</td></tr><tr><td><code>lertaro://search/[keyword]</code></td><td><code>[keyword]</code> を入力済みの状態でクイック検索ウィンドウをアクティブにします。</td></tr><tr><td><code>lertaro://fullsearch/[keyword]</code></td><td><code>[keyword]</code> を入力済みの状態でフル検索ウィンドウを開きます。</td></tr><tr><td><code>lertaro://settings/page/[section]</code></td><td>設定を指定したトップレベルのセクションで開きます。</td></tr><tr><td><code>lertaro://settings/entry/[index]</code></td><td>設定を開き、指定した特定の設定項目までジャンプしてハイライトします。</td></tr><tr><td><code>lertaro://localsend</code></td><td>空の LocalSend 送信ウィンドウを開きます。</td></tr><tr><td><code>lertaro://localsend/items[/encoded-item...]</code></td><td>ファイル/フォルダーモードに切り替え、必要に応じて項目ごとに1つのエンコード済みパスセグメントを追加します。</td></tr><tr><td><code>lertaro://localsend/text[/encoded-text]</code></td><td>テキストモードに切り替え、必要に応じてエンコード済みテキストを入力します。</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lertaro://search/report</span></span>
<span class="line"><span>lertaro://settings/page/Appearance</span></span></code></pre></div><p>1つ目は「report」であらかじめ絞り込まれた状態でクイック検索ウィンドウをアクティブにし、2つ目は設定を外観のページで直接開きます。</p><p><code>[section]</code> はトップレベルのサイドバー項目のいずれかに一致します:<code>Service</code>、<code>Index</code>、<code>General</code>、<code>Appearance</code>、<code>Hotkeys</code>、<code>Plugins</code>、<code>Favorites</code>、<code>History</code>、<code>QuickPanel</code>、<code>About</code> — 大文字小文字は区別されません。</p><p><code>[index]</code> は手入力を想定したものではありません — <a href="./instant-answers.html">設定検索</a>が、選択した設定に対して自動的に生成する番号であり、その検索結果の1つを選択すると、そのまま該当する行に直接戻ってこられる仕組みになっています。再起動をまたいでは安定しないため、特定の番号がそのまま維持されることを前提にしないでください。</p><h2 id="localsend-リンク" tabindex="-1">LocalSend リンク <a class="header-anchor" href="#localsend-リンク" aria-label="Permalink to &quot;LocalSend リンク&quot;">​</a></h2><p>各ファイル/フォルダーパスまたはテキスト値は、1つの完全な URL パスセグメントとしてエンコードする必要があります。複数の項目を追加するには、項目ごとに1つのエンコード済みセグメントを追加します。すべてのパスは既に存在する絶対パスでなければなりません。例:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lertaro://localsend/items/C%3A%5CUsers%5Ctestuser%5CDesktop%5Ca.txt/D%3A%5CShared</span></span>
<span class="line"><span>lertaro://localsend/text/Hello%20world</span></span></code></pre></div><p><code>lertaro://localsend/items</code> は収集ページをファイル/フォルダーモードで開き、<code>lertaro://localsend/text</code> はテキストモードで開きます。内容を含むリンクはデバイス選択に進みますが、デバイスを自動選択したり転送を自動開始したりすることはありません。送信ウィンドウが既に開いている場合、リンクは何もせず、現在の内容や状態も変更しません。LocalSend が無効の場合は、代わりに LocalSend の設定ページが開きます。無効または長すぎる内容がある場合、リクエスト全体が無視されます。</p><h2 id="認識されないリンク" tabindex="-1">認識されないリンク <a class="header-anchor" href="#認識されないリンク" aria-label="Permalink to &quot;認識されないリンク&quot;">​</a></h2><p>既知のルートに一致しないもの(タイプミス、サポートされていないセクション、<code>lertaro://</code> の後のでたらめな文字列など)は黙って無視されます。どのウェブサイトやアプリでも確認なしにこのプロトコルを呼び出せるため、不正または想定外のリンクが予期しない動作を引き起こすことは決してあってはなりません。トラブルシューティングのためにログには記録されますが、それ以外は何も起こりません。</p>`,15)])])}const b=t(r,[["render",c]]);export{u as __pageData,b as default};
